using DadoRetail.Api.Security;using DadoRetail.Application.Security;using DadoRetail.Infrastructure.Persistence;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;namespace DadoRetail.Api.Controllers;[ApiController,Route("api/v1/organization")]public sealed class OrganizationController(DadoRetailDbContext db):ControllerBase{[HttpGet("stores"),HasPermission(Permissions.SaleCreate)]public async Task<IActionResult>Stores(CancellationToken ct)=>Ok(await db.Stores.AsNoTracking().Where(x=>x.IsActive).OrderBy(x=>x.Code).Select(x=>new{x.Id,x.Code,x.Name}).ToListAsync(ct));[HttpGet("warehouses"),HasPermission(Permissions.SaleCreate)]public async Task<IActionResult>Warehouses([FromQuery]Guid storeId,CancellationToken ct)=>Ok(await db.Warehouses.AsNoTracking().Where(x=>x.StoreId==storeId).OrderBy(x=>x.Code).Select(x=>new{x.Id,x.StoreId,x.Code,x.Name}).ToListAsync(ct));[HttpGet("cash-registers"),HasPermission(Permissions.SaleCreate)]public async Task<IActionResult>Registers([FromQuery]Guid storeId,CancellationToken ct)=>Ok(await db.CashRegisters.AsNoTracking().Where(x=>x.StoreId==storeId&&x.IsActive).OrderBy(x=>x.Code).Select(x=>new{x.Id,x.StoreId,x.Code}).ToListAsync(ct));}
